import React, { useState, useEffect } from "react";
import "./Test.css";

const Test = ({ messages }) => {
  const [previousTopics, setPreviousTopics] = useState([]);
  const [selectedTopic, setSelectedTopic] = useState("");
  const [questions, setQuestions] = useState([]);
  const [selectedAnswers, setSelectedAnswers] = useState({});
  const [score, setScore] = useState(null);

  // Extract topics dynamically from chat messages
  useEffect(() => {
    const topics = new Set();
    messages.forEach((msg) => {
      if (msg.user) {
        const words = msg.user.split(" ");
        words.forEach((word) => {
          if (word.length > 3) topics.add(word);
        });
      }
    });
    setPreviousTopics([...topics]);
  }, [messages]);

  const handleTopicSelect = (topic) => {
    setSelectedTopic(topic);
    generateQuestions(topic);
    setScore(null);
  };

  // Generate dummy MCQs based on topic (replace with AI-based questions later)
  const generateQuestions = (topic) => {
    const sampleQuestions = [
      {
        question: `What is ${topic}?`,
        options: ["Definition", "Function", "Example", "None"],
        correct: "Definition",
      },
      {
        question: `How does ${topic} work?`,
        options: ["Method A", "Method B", "Method C", "None"],
        correct: "Method A",
      },
    ];
    setQuestions(sampleQuestions);
    setSelectedAnswers({});
  };

  // Handle answer selection
  const handleAnswerSelect = (qIndex, option) => {
    setSelectedAnswers((prev) => ({ ...prev, [qIndex]: option }));
  };

  // Calculate Score
  const handleSubmit = () => {
    let correctCount = 0;
    questions.forEach((q, index) => {
      if (selectedAnswers[index] === q.correct) {
        correctCount++;
      }
    });
    setScore(correctCount);
  };

  return (
    <div className="test-container">
      <h2>Test Your Knowledge</h2>

      <div className="topic-selection">
        <h3>Select a Topic:</h3>
        {previousTopics.length > 0 ? (
          previousTopics.map((topic, index) => (
            <button key={index} onClick={() => handleTopicSelect(topic)}>
              {topic}
            </button>
          ))
        ) : (
          <p>No topics available. Start a chat to generate topics.</p>
        )}
      </div>

      {selectedTopic && (
        <div className="questions-section">
          <h3>Questions for: {selectedTopic}</h3>
          {questions.map((q, index) => (
            <div key={index} className="question">
              <p>{q.question}</p>
              {q.options.map((option, idx) => (
                <button
                  key={idx}
                  onClick={() => handleAnswerSelect(index, option)}
                  className={
                    selectedAnswers[index] === option ? "selected" : ""
                  }
                >
                  {option}
                </button>
              ))}
            </div>
          ))}
          <button onClick={handleSubmit} className="submit-btn">
            Submit
          </button>
        </div>
      )}

      {score !== null && (
        <div className="score-section">
          <h3>Your Score: {score} / {questions.length}</h3>
        </div>
      )}
    </div>
  );
};

export default Test;
